changeSet.sql:
CREATE TABLE questionary_type(
    id bigserial PRIMARY KEY,
    name varchar(50) NOT NULL UNIQUE,
    description text,
    factor_lambda_part float
);

CREATE INDEX questionary_type_name_idx ON questionary_type(name);

CREATE TABLE question_block(
    id bigserial PRIMARY KEY,
    questionary_type_id bigint NOT NULL REFERENCES questionary_type(id),
    name varchar(50),
    description text,
    ordering int8
);

CREATE INDEX question_block_name_idx ON question_block(name);
CREATE INDEX question_block_type_id_idx ON question_block(questionary_type_id);

CREATE TABLE question(
    id bigserial PRIMARY KEY,
    question_block_id bigint NOT NULL REFERENCES question_block(id),
    type varchar(25) NOT NULL,
    title varchar(50) NOT NULL,
    description text,
    ordering int8,
    for_semantic_similarity boolean NOT NULL default false,
    weight_coefficient_for_vector float NOT NULL default 1
);

CREATE INDEX question_type_idx ON question(type);
CREATE INDEX question_question_block_idx ON question(question_block_id);

CREATE TABLE answer_option(
    id bigserial PRIMARY KEY,
    option_key varchar(2) NOT NULL,
    question_id bigint NOT NULL REFERENCES question(id),
    value text,
    ordering int8,
    influence float[]
);

CREATE UNIQUE INDEX answer_option_key_idx ON answer_option(option_key, question_id);

CREATE TABLE questionary(
    id bigserial PRIMARY KEY,
    name varchar(50) NOT NULL,
    status varchar(50) NOT NULL DEFAULT 'DRAFT',
    questionary_type_id bigint NOT NULL REFERENCES questionary_type(id),
    created_at timestamp NOT NULL default current_timestamp,
    user_id bigint NOT NULL,
    vectors_initialized boolean NOT NULL DEFAULT false,
    semantic_vector vector(384),
    factor_vector vector(16)
);

CREATE INDEX questionary_name_idx ON questionary(name);
CREATE INDEX questionary_type_idx ON questionary(questionary_type_id);
CREATE INDEX questionary_user_idx ON questionary(user_id);
CREATE INDEX questionary_status_idx ON questionary(status);
CREATE INDEX questionary_semantic_vector_idx ON questionary USING ivfflat(semantic_vector);
CREATE INDEX questionary_factor_vector_idx ON questionary USING ivfflat(factor_vector);

CREATE TABLE answer(
    id bigserial PRIMARY KEY,
    questionary_id bigint NOT NULL REFERENCES questionary(id),
    question_id bigint NOT NULL REFERENCES question(id),
    text_value text,
    numeric_value float,
    chosen_options_keys varchar(2)[]
);

CREATE INDEX answer_questionary_id_idx ON answer(questionary_id);
CREATE INDEX answer_question_id_idx ON answer(question_id);
CREATE INDEX answer_numeric_value_id_idx ON answer(numeric_value);
CREATE INDEX answer_chosen_options_keys_idx ON answer USING GIN(chosen_options_keys);
CREATE UNIQUE INDEX answer_question_questionary_idx ON answer(question_id, questionary_id);

CREATE TABLE similarity_factor(
    vector_index int8 PRIMARY KEY,
    name varchar(100) NOT NULL UNIQUE
);

CREATE INDEX similarity_factor_name_idx ON similarity_factor(name);

