CREATE TABLE questionary_filter(
    id bigserial PRIMARY KEY,
    question_id bigint NOT NULL REFERENCES question(id),
    filter_type varchar(25) NOT NULL,
    is_public boolean NOT NULL default true,
    default_options_in_set_keys varchar(2)[],
    default_numeric_value_from float,
    default_numeric_value_to float
);

CREATE INDEX questionary_filter_question_id_idx ON questionary_filter(question_id);
CREATE INDEX questionary_filter_type_idx ON questionary_filter(filter_type);
